import{_ as n,C as e,o as s,c,E as a,a7 as l}from"./chunks/framework.FWlv_suP.js";const v=JSON.parse('{"title":"AR Tamizh Solai Privacy Policy","description":"Privacy Policy for AR Tamizh Solai, presented within Policy Hub.","frontmatter":{"title":"AR Tamizh Solai Privacy Policy","description":"Privacy Policy for AR Tamizh Solai, presented within Policy Hub."},"headers":[],"relativePath":"apps/artamizhsolai/privacy.md","filePath":"apps/artamizhsolai/privacy.md"}'),d={name:"apps/artamizhsolai/privacy.md"};function h(p,o,u,m,y,b){const r=e("AppBreadcrumbs"),i=e("AppSubnav"),t=e("CopyStandaloneUrl");return s(),c("div",null,[a(r,{"app-id":"artamizhsolai",current:"Privacy Policy"}),a(i,{"app-id":"artamizhsolai"}),a(t,{path:"/privacy/artamizhsolai","document-name":"AR Tamizh Solai privacy policy"}),o[0]||(o[0]=l('<h1 id="privacy-policy-for-ar-tamizh-solai" tabindex="-1">Privacy Policy for AR Tamizh Solai <a class="header-anchor" href="#privacy-policy-for-ar-tamizh-solai" aria-label="Permalink to &quot;Privacy Policy for AR Tamizh Solai&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AR Tamizh Solai is an independent Tamil literature and culture publication by <strong>Anand Raja</strong>. It provides articles, archives, site search, media embeds, a contact form, social links, optional donations, and limited password-protected content.</p><p>AR Tamizh Solai does not currently offer reader accounts, public comments, or a newsletter. No visitor analytics service was found in the reviewed production source.</p><h2 id="information-you-submit" tabindex="-1">Information You Submit <a class="header-anchor" href="#information-you-submit" aria-label="Permalink to &quot;Information You Submit&quot;">​</a></h2><p>The contact form collects your name, email address, inquiry purpose, and message. You may optionally provide a phone number and the URL of the content concerned. The form sends this information directly to Google Forms, where it is available to Google and the publisher. It is used to respond to questions, review corrections or suggestions, discuss contributions or collaboration, and handle support, copyright, or privacy requests.</p><p>Do not submit passwords, payment credentials, or unnecessary sensitive personal information. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><h2 id="browser-storage-and-protected-articles" tabindex="-1">Browser Storage and Protected Articles <a class="header-anchor" href="#browser-storage-and-protected-articles" aria-label="Permalink to &quot;Browser Storage and Protected Articles&quot;">​</a></h2><p>Some articles may require a publisher-provided password. Password validation occurs in your browser by comparing a SHA-1 hash. After a successful unlock, the site stores the matching hash and a timestamp in localStorage for up to 24 hours. The plain-text password is not stored or sent to an AR Tamizh Solai server.</p><p>The site can temporarily store a pending protected route in sessionStorage while showing the password prompt. These records are not reader accounts and can be removed by clearing the site&#39;s browser data. Client-side article protection should not be treated as strong security against someone who can inspect delivered website files.</p><h2 id="search-hosting-and-technical-logs" tabindex="-1">Search, Hosting, and Technical Logs <a class="header-anchor" href="#search-hosting-and-technical-logs" aria-label="Permalink to &quot;Search, Hosting, and Technical Logs&quot;">​</a></h2><p>Site search works against published content in the browser; search words are not sent to an AR Tamizh Solai search server.</p><p>The site is published through Cloudflare Pages and GitHub Pages. The hosting provider serving your visit can receive ordinary technical data such as your IP address, browser and device details, requested URL, referrer, timestamps, and security or diagnostic information under its own policies.</p><h2 id="embeds-social-links-and-external-services" tabindex="-1">Embeds, Social Links, and External Services <a class="header-anchor" href="#embeds-social-links-and-external-services" aria-label="Permalink to &quot;Embeds, Social Links, and External Services&quot;">​</a></h2><p>Selected articles can load videos or social posts from providers such as YouTube, Instagram, Facebook, TikTok, or Dailymotion. Loading or interacting with an embed may disclose your IP address, browser details, referrer, cookies, account state, and interaction information to that provider.</p><p>Social profiles, cited sources, and other external links are operated independently. Their privacy practices are outside AR Tamizh Solai&#39;s control.</p><h2 id="donations" tabindex="-1">Donations <a class="header-anchor" href="#donations" aria-label="Permalink to &quot;Donations&quot;">​</a></h2><p>Articles may show a Google Pay or UPI QR code and links to PayPal, Buy Me a Coffee, GitHub Sponsors, or Ko-fi. AR Tamizh Solai does not directly receive or store your card, bank-account, or payment-login credentials. A provider you choose processes the transaction and related information under its own terms and privacy policy.</p><h2 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to &quot;Cookies&quot;">​</a></h2><p>AR Tamizh Solai does not set its own advertising cookies. Hosting providers, embedded media, donation services, or other external providers may use cookies or similar technologies when their content is loaded or opened. You can control cookies and local storage through your browser.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Browser access records remain until they expire, are replaced, or you clear site data. Contact submissions remain with Google and the publisher until they are deleted or no longer reasonably needed, subject to legal, security, and operational requirements.</p><p>To request access, correction, or deletion of a contact submission, email the address below with enough non-sensitive information to identify it. Information controlled solely by a host, embed, social network, or payment provider must be handled by that provider.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>AR Tamizh Solai is a general-audience educational publication and is not designed to collect personal information from children. A child should not submit the contact form or make a donation without appropriate parent or guardian involvement.</p><h2 id="changes-and-contact" tabindex="-1">Changes and Contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and Contact&quot;">​</a></h2><p>This policy may be updated when website features, providers, or data practices change.</p><ul><li><strong>Publisher:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',29))])}const f=n(d,[["render",h]]);export{v as __pageData,f as default};
